param([switch]$SkipBuild)
$ErrorActionPreference='Stop'; $workspace=(Resolve-Path (Join-Path $PSScriptRoot '..')).Path; $output=Join-Path $workspace 'docs\evidence\post-v115-m1b1c-pptx-drafts'; Remove-Item $output -Recurse -Force -ErrorAction SilentlyContinue; New-Item -ItemType Directory $output -Force|Out-Null
& npm run check:post-v115-m1b1c-pptx-drafts; if($LASTEXITCODE-ne 0){throw 'M1B1C contract check failed'}
if(-not $SkipBuild){& npm run build; if($LASTEXITCODE-ne 0){throw 'Production build failed'}; $env:TAURI_CONFIG=Get-Content -LiteralPath (Join-Path $workspace 'src-tauri\tauri.e2e.conf.json') -Raw; & cargo build --locked --manifest-path (Join-Path $workspace 'src-tauri\Cargo.toml') --bin tauri-app; if($LASTEXITCODE-ne 0){throw 'Tauri build failed'}}
$root=Join-Path $env:TEMP ("longedit-m1b1c-{0}"-f [DateTimeOffset]::UtcNow.ToUnixTimeMilliseconds());$library=Join-Path $root 'library';$webview=Join-Path $root 'webview';New-Item -ItemType Directory $library,$webview -Force|Out-Null;$fixture=Join-Path $library 'wps-m1b1c.pptx';Copy-Item (Join-Path $workspace 'fixtures\pptx\producers\wps-presentation.pptx') $fixture;Copy-Item (Join-Path $workspace 'fixtures\pptx\producers\wps-presentation.pptx') (Join-Path $library 'wps-m1b1c-secondary.pptx')
$vite=Start-Process npm.cmd -ArgumentList 'run','dev','--','--host','127.0.0.1','--port','9000' -WorkingDirectory $workspace -WindowStyle Hidden -PassThru; try{for($i=0;$i-lt 180-and-not(Get-NetTCPConnection -LocalPort 9000 -State Listen -ErrorAction SilentlyContinue);$i++){Start-Sleep -Milliseconds 100};$env:LONGEDIT_E2E_LIBRARY=$library;$env:LONGEDIT_E2E_THEME='white';$env:LONGEDIT_E2E_STYLE='minimal';$env:LONGEDIT_E2E_CODE_THEME='github';$env:LONGEDIT_E2E_MOTION='reduced';$env:WEBVIEW2_USER_DATA_FOLDER=$webview;$env:WEBVIEW2_ADDITIONAL_BROWSER_ARGUMENTS='--remote-debugging-port=9333 --remote-allow-origins=*';$app=Start-Process (Join-Path $workspace 'src-tauri\target\debug\tauri-app.exe') -WorkingDirectory (Join-Path $workspace 'src-tauri') -PassThru;try{for($i=0;$i-lt 180-and-not(Get-NetTCPConnection -LocalPort 9333 -State Listen -ErrorAction SilentlyContinue);$i++){Start-Sleep -Milliseconds 100};$env:LONGEDIT_CDP_ENDPOINT='http://127.0.0.1:9333';$env:LONGEDIT_M1B1C_AUDIT_OUTPUT=$output;$env:LONGEDIT_M1B1C_FIXTURE=$fixture;& node (Join-Path $workspace 'scripts\capture-post-v115-m1b1c-pptx-drafts.mjs');if($LASTEXITCODE-ne 0){throw 'Desktop audit failed'}}finally{if($app-and-not$app.HasExited){Stop-Process $app.Id -Force}}}finally{if($vite-and-not$vite.HasExited){Stop-Process $vite.Id -Force};Get-NetTCPConnection -LocalPort 9000 -State Listen -ErrorAction SilentlyContinue|ForEach-Object{Stop-Process $_.OwningProcess -Force -ErrorAction SilentlyContinue}}
Write-Output "M1B1C audit completed: $output"
